mapper.insert:
INSERT
  INTO adv02_account
SELECT f_create_seq()
     , #{p.companyId}
     , #{p.manageCode}
     , #{p.manageName}
     , #{p.trCorpCode}
     , #{p.trCorpName}
     , TO_ENCRYPTS(#{p.accountNoDec})
     , #{p.startDate}
     , #{p.closeDate}
     , f_sysdate()
     , #{p.worker}

mapper.update:
UPDATE adv02_account
   SET adv02_manage_nm  = #{p.manageName}
     , adv02_tr_corp_cd = #{p.trCorpCode}
     , adv02_tr_corp_nm = #{p.trCorpName}
     , adv02_account_no = TO_ENCRYPTS(#{p.accountNoDec})
     , adv02_start_date = #{p.startDate}
     , adv02_close_date = #{p.closeDate}
     , adv02_work_date  = f_sysdate()
     , adv02_worker     = #{p.worker}
 WHERE adv02_account_id = #{p.accountId}

mapper.select:
SELECT sys15_corp_id      AS corpId
     , sys15_company_id   AS companyId
     , sys15_corp_nm      AS corpName
     , sys15_corp_type    AS corpType
     , sys15_corp_cd      AS corpCode
  FROM sys15_corp
 WHERE sys15_company_id = #{companyId}
   AND sys15_corp_type  = #{corpType}
   AND sys15_corp_nm    = #{corpName}

